//! CacheStage behaviour against in-memory stores (no Valkey/Postgres/Ollama), plus the
//! Python-parity goldens in `tests/fixtures/python_golden.json` (generated by running the real
//! `shared/cache/{keys,replay}.py` + orjson). Live-Valkey checks are `#[ignore]` at the bottom.

mod common;

use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::{Arc, Mutex};
use std::time::Duration;

use cache::{derive_exact_key, ExactKeyParts};
use common::*;
use futures_util::StreamExt;
use pipeline::{
    CacheStatus, PipelineContext, ProxyPipeline, ResponseFormat, Stage, StageError,
    StaticFlagResolver,
};
use respcache::{
    commit_write_back, replay_anthropic_sse, replay_openai_sse, AffinityStore, CacheStage,
    CachedResponse, ExactStore, ResolvedCacheConfig, ResponseCache, RESPONSE_CACHE_FLAG,
};
use serde_json::{json, Value};

fn golden() -> Value {
    serde_json::from_str(include_str!("fixtures/python_golden.json")).expect("golden json")
}

/// Runs a miss lookup and commits `body` so a later identical request hits.
async fn seed(r: &Rig, c: &PipelineContext, body: &Value) {
    let res = r.cache.lookup(c).await;
    let wb = res.write_back.expect("miss carries a write-back");
    wb.commit(body, &body["usage"]).await;
}

#[test]
fn exact_key_bytes_match_python() {
    let g = golden();
    let cases = g["cases"].as_array().expect("cases");
    assert_eq!(cases.len(), 4, "denominator: every golden case is checked");
    for case in cases {
        let p = &case["parts"];
        let messages = p["messages"].as_array().expect("messages");
        let tools = (!p["tools"].is_null()).then(|| p["tools"].clone());
        let top_p = (!p["top_p"].is_null()).then(|| p["top_p"].clone());
        let max_tokens = (!p["max_tokens"].is_null()).then(|| p["max_tokens"].clone());
        let parts = ExactKeyParts {
            org_id: p["org_id"].as_i64().unwrap(),
            model_class: p["model_class"].as_str().unwrap(),
            messages,
            tools: tools.as_ref(),
            temperature: p["temperature"].as_f64().unwrap(),
            top_p: top_p.as_ref(),
            max_tokens: max_tokens.as_ref(),
        };
        assert_eq!(derive_exact_key(&parts), case["sha256"].as_str().unwrap());
    }
}

#[tokio::test]
async fn stage_derives_the_python_key_including_response_format() {
    let g = golden();
    let r = rig();
    let openai = r
        .cache
        .lookup(&ctx(7, "gpt-4o", ResponseFormat::Openai, "What is Rust?"))
        .await;
    let anth = r
        .cache
        .lookup(&ctx(
            7,
            "gpt-4o",
            ResponseFormat::Anthropic,
            "What is Rust?",
        ))
        .await;
    assert_eq!(
        openai.write_back.unwrap().key,
        g["cases"][0]["sha256"].as_str().unwrap()
    );
    assert_eq!(
        anth.write_back.unwrap().key,
        g["cases"][1]["sha256"].as_str().unwrap()
    );
}

#[tokio::test]
async fn openai_and_anthropic_requests_never_share_entry() {
    let r = rig();
    let oa = ctx(7, "gpt-4o", ResponseFormat::Openai, "What is Rust?");
    seed(&r, &oa, &openai_body("Rust is a language.")).await;
    assert_eq!(r.cache.lookup(&oa).await.status, CacheStatus::Exact);
    let an = ctx(7, "gpt-4o", ResponseFormat::Anthropic, "What is Rust?");
    let res = r.cache.lookup(&an).await;
    assert_eq!(res.status, CacheStatus::Miss, "formats must not collide");
    assert!(res.cached.is_none());
    assert_eq!(r.exact.map.lock().unwrap().len(), 1);
    // org isolation: same request, other org, never a hit
    let other = ctx(8, "gpt-4o", ResponseFormat::Openai, "What is Rust?");
    assert_eq!(r.cache.lookup(&other).await.status, CacheStatus::Miss);
}

#[tokio::test]
async fn exact_hit_populates_ctx_provider_cache() {
    let r = rig();
    let first = ctx(7, "gpt-4o", ResponseFormat::Openai, "What is Rust?");
    seed(&r, &first, &openai_body("Rust is a language.")).await;
    let stage = CacheStage::new(r.cache.clone());
    assert_eq!(stage.name(), "cache");
    assert_eq!(stage.flag(), Some("waddleai.response_cache"));
    let mut c = ctx(7, "gpt-4o", ResponseFormat::Openai, "What is Rust?");
    stage.call(&mut c).await.unwrap();
    assert_eq!(c.provider.as_deref(), Some("cache"));
    assert!(c.cache_hit);
    assert_eq!(c.cache_status, CacheStatus::Exact);
    assert_eq!(c.tokens_saved, 14);
    assert_eq!(c.response_text, "Rust is a language.");
    assert_eq!(c.finish_reason.as_deref(), Some("stop"));
    let u = c.usage.expect("usage");
    assert_eq!((u.input_tokens, u.output_tokens), (5, 9));
    assert!(c.stream_iter.is_none(), "non-streaming hit has no replay");
    assert!(c.cache_write_back.is_none());
    assert_eq!(lookups(&r.metrics, "exact", "hit"), 1.0);
}

#[tokio::test]
async fn semantic_hit_above_threshold_miss_below() {
    let emb = FakeEmbedder::with(&[
        ("What is Rust?", vec![1.0, 0.0, 0.0]),
        ("Tell me what Rust is?", vec![0.99, 0.1, 0.0]),
        ("What is Go?", vec![0.0, 1.0, 0.0]),
    ]);
    let (r, store) = semantic_rig(emb);
    let seed_ctx = ctx(7, "gpt-4o", ResponseFormat::Openai, "What is Rust?");
    seed(&r, &seed_ctx, &openai_body("Rust is a language.")).await;
    assert_eq!(
        store.rows.lock().unwrap().len(),
        1,
        "semantic entry written"
    );

    let near = ctx(7, "gpt-4o", ResponseFormat::Openai, "Tell me what Rust is?");
    let hit = r.cache.lookup(&near).await;
    assert_eq!(hit.status, CacheStatus::Semantic);
    assert!(hit.cached.is_some());
    assert_eq!(store.hits.lock().unwrap().as_slice(), &[1]);

    let far = ctx(7, "gpt-4o", ResponseFormat::Openai, "What is Go?");
    let miss = r.cache.lookup(&far).await;
    assert_eq!(miss.status, CacheStatus::Miss);
    assert!(miss.write_back.is_some());
}

#[tokio::test]
async fn embedding_unavailable_degrades_to_exact_only_visibly() {
    use tracing_subscriber::layer::SubscriberExt;
    let logs: Arc<Mutex<Vec<(tracing::Level, String)>>> = Arc::default();
    let sub = tracing_subscriber::registry().with(Capture(logs.clone()));
    let _guard = tracing::subscriber::set_default(sub);

    let emb = FakeEmbedder::with(&[("What is Rust?", vec![1.0, 0.0, 0.0])]);
    let (r, store) = semantic_rig(emb.clone());
    // exact entry exists (written while the embedder was healthy)
    let c0 = ctx(7, "gpt-4o", ResponseFormat::Openai, "What is Rust?");
    seed(&r, &c0, &openai_body("Rust is a language.")).await;
    emb.fail.store(true, Ordering::SeqCst);

    // exact layer still serves
    assert_eq!(r.cache.lookup(&c0).await.status, CacheStatus::Exact);

    // a miss degrades: no semantic hit, request not failed, bypass is counted and logged
    let c1 = ctx(7, "gpt-4o", ResponseFormat::Openai, "What is Go?");
    let res = r.cache.lookup(&c1).await;
    assert_eq!(res.status, CacheStatus::Miss);
    assert!(res.write_back.is_some(), "exact write-back still stashed");
    assert_eq!(lookups(&r.metrics, "semantic", "bypass"), 1.0);
    assert!(store.hits.lock().unwrap().is_empty());
    let seen = logs.lock().unwrap().clone();
    assert!(
        seen.iter()
            .any(|(l, m)| *l == tracing::Level::WARN && m.contains("embedding unavailable")),
        "degradation must be logged at WARN, got {seen:?}"
    );
    assert!(
        !seen.iter().any(|(_, m)| m.contains("What is Go?")),
        "prompt text must never be logged"
    );
}

#[tokio::test]
async fn miss_stashes_write_back_and_preferred_backend() {
    let r = rig();
    // rebuild with affinity
    let aff = Arc::new(MemAffinity::default());
    aff.record(7, "sess-1", "pod-a").await;
    let cache = Arc::new(
        ResponseCache::new(
            r.exact.clone(),
            Arc::new(FixedConfig(ResolvedCacheConfig::default())),
            flags(),
            r.metrics.clone(),
        )
        .with_affinity(aff),
    );
    let stage = CacheStage::new(cache);
    let mut c = ctx(7, "gpt-4o", ResponseFormat::Openai, "What is Rust?");
    c.body["session_id"] = json!("sess-1");
    stage.call(&mut c).await.unwrap();
    assert_eq!(c.cache_status, CacheStatus::Miss);
    assert!(!c.cache_hit && c.provider.is_none());
    let wb = c.cache_write_back.as_ref().expect("write-back stashed");
    assert_eq!(wb.key.len(), 64);
    assert!(wb.sink.is_some());
    assert_eq!(c.preferred_backend.as_deref(), Some("pod-a"));
    assert_eq!(r.exact.puts.load(Ordering::SeqCst), 0, "no write at lookup");
    assert_eq!(lookups(&r.metrics, "exact", "miss"), 1.0);

    // unknown session -> no hint
    let mut c2 = ctx(7, "gpt-4o", ResponseFormat::Openai, "other?");
    c2.body["session_id"] = json!("nope");
    stage.call(&mut c2).await.unwrap();
    assert!(c2.preferred_backend.is_none());
}

#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn singleflight_collapses_concurrent_identical_requests() {
    const N: usize = 8;
    let r = rig();
    let (tx, mut rx) = tokio::sync::mpsc::unbounded_channel();
    for _ in 0..N {
        let cache = r.cache.clone();
        let tx = tx.clone();
        tokio::spawn(async move {
            let c = ctx(7, "gpt-4o", ResponseFormat::Openai, "What is Rust?");
            let res = cache.lookup(&c).await;
            let _ = tx.send(res);
        });
    }
    drop(tx);
    // The leader returns immediately (a miss with the lease); followers block on it.
    let leader = rx.recv().await.expect("leader result");
    assert_eq!(leader.status, CacheStatus::Miss);
    let wb = leader.write_back.expect("leader holds the write-back");
    tokio::time::sleep(Duration::from_millis(150)).await;
    assert!(
        rx.try_recv().is_err(),
        "followers must wait for the leader, not dispatch"
    );
    wb.commit(
        &openai_body("Rust is a language."),
        &json!({"total_tokens": 14}),
    )
    .await;
    let mut hits = 0;
    while let Some(res) = rx.recv().await {
        assert_eq!(
            res.status,
            CacheStatus::Exact,
            "follower gets leader's value"
        );
        assert!(res.write_back.is_none());
        hits += 1;
    }
    assert_eq!(hits, N - 1, "exactly one leader, N-1 collapsed followers");
    assert_eq!(r.exact.puts.load(Ordering::SeqCst), 1);
    assert_eq!(
        lookups(&r.metrics, "exact", "stampede_wait"),
        (N - 1) as f64
    );
}

#[tokio::test]
async fn abandoned_leader_releases_followers_to_compute() {
    let r = rig();
    let first = ctx(7, "gpt-4o", ResponseFormat::Openai, "What is Rust?");
    let leader = r.cache.lookup(&first).await;
    let cache = r.cache.clone();
    let follower = tokio::spawn(async move {
        let c = ctx(7, "gpt-4o", ResponseFormat::Openai, "What is Rust?");
        cache.lookup(&c).await
    });
    tokio::time::sleep(Duration::from_millis(100)).await;
    drop(leader); // request blocked/errored: write-back never committed
    let res = tokio::time::timeout(Duration::from_secs(2), follower)
        .await
        .expect("follower released promptly, not after the full wait timeout")
        .unwrap();
    assert_eq!(res.status, CacheStatus::Miss);
    assert!(res.write_back.is_some(), "follower becomes the new leader");
    assert_eq!(lookups(&r.metrics, "exact", "stampede_fallthrough"), 1.0);
}

#[tokio::test]
async fn streaming_hit_sets_stream_iter_replay_event_sequence_equals_python() {
    let g = golden();
    let r = rig();
    for (fmt, model, key) in [
        (ResponseFormat::Openai, "gpt-4o", "openai"),
        (ResponseFormat::Anthropic, "claude-3", "anthropic"),
    ] {
        let body = g[key]["body"].clone();
        let c0 = ctx(7, model, fmt, "What is Rust?");
        let res = r.cache.lookup(&c0).await;
        res.write_back.unwrap().commit(&body, &body["usage"]).await;

        let stage = CacheStage::new(r.cache.clone());
        let mut c = ctx(7, model, fmt, "What is Rust?");
        c.stream = true;
        stage.call(&mut c).await.unwrap();
        assert!(c.cache_hit);
        let frames: Vec<String> = c
            .stream_iter
            .take()
            .expect("streaming hit sets stream_iter")
            .map(|b| String::from_utf8(b.expect("no io error").to_vec()).unwrap())
            .collect()
            .await;
        assert_same_sse(&frames, g[key]["frames"].as_array().unwrap());
    }
}

/// Frames are compared as (event header, parsed JSON): framing bytes match Python exactly,
/// JSON compares structurally because serde_json does not preserve object key insertion order.
fn assert_same_sse(got: &[String], want: &[Value]) {
    assert_eq!(got.len(), want.len(), "frame count: {got:?}");
    assert!(!got.is_empty(), "zero frames examined is a failure");
    for (g, w) in got.iter().zip(want) {
        let w = w.as_str().unwrap();
        assert!(g.ends_with("\n\n") && w.ends_with("\n\n"));
        let (gh, gj) = g.split_once("data: ").expect("data line");
        let (wh, wj) = w.split_once("data: ").expect("data line");
        assert_eq!(gh, wh, "event header");
        if gj.trim() == "[DONE]" || wj.trim() == "[DONE]" {
            assert_eq!(gj, wj);
            continue;
        }
        let gv: Value = serde_json::from_str(gj.trim()).unwrap();
        let wv: Value = serde_json::from_str(wj.trim()).unwrap();
        assert_eq!(gv, wv, "frame payload");
    }
}

#[tokio::test]
async fn replay_functions_match_python_directly() {
    let g = golden();
    let ob = g["openai"]["body"].clone();
    let cached = CachedResponse {
        usage: ob["usage"].clone(),
        response: ob,
        stored_at: 0.0,
    };
    let frames: Vec<String> = replay_openai_sse(&cached)
        .map(|b| String::from_utf8(b.unwrap().to_vec()).unwrap())
        .collect()
        .await;
    assert_same_sse(&frames, g["openai"]["frames"].as_array().unwrap());
    let ab = g["anthropic"]["body"].clone();
    let cached = CachedResponse {
        usage: ab["usage"].clone(),
        response: ab,
        stored_at: 0.0,
    };
    let frames: Vec<String> = replay_anthropic_sse(&cached)
        .map(|b| String::from_utf8(b.unwrap().to_vec()).unwrap())
        .collect()
        .await;
    assert_same_sse(&frames, g["anthropic"]["frames"].as_array().unwrap());
}

#[derive(Default)]
struct Counting(AtomicUsize);

/// Stands in for the real dispatch stage: Python's DispatchStage returns first on `cache_hit`.
struct FakeDispatch(Arc<Counting>);

#[async_trait::async_trait]
impl Stage for FakeDispatch {
    fn name(&self) -> &'static str {
        "dispatch"
    }
    async fn call(&self, ctx: &mut PipelineContext) -> Result<(), StageError> {
        if ctx.cache_hit {
            return Ok(());
        }
        self.0 .0.fetch_add(1, Ordering::SeqCst);
        ctx.provider = Some("ollama".into());
        Ok(())
    }
}

mod quota_fake {
    use std::sync::atomic::{AtomicUsize, Ordering};
    use std::sync::Arc;

    use auth::UserContext;
    use quota::{
        CreditError, CreditModel, Outcome, QuotaBackend, QuotaError, ReconcileResult, Reservation,
    };
    use serde_json::Value;

    pub struct NoCredits;
    impl CreditModel for NoCredits {
        fn estimate_credits(&self, _m: &str, _i: u64, _o: u64) -> u64 {
            1
        }
        fn providers_for_model(&self, _m: &str) -> std::collections::HashSet<String> {
            Default::default()
        }
        fn count_tokens(&self, _t: &str, _p: &str, _m: &str) -> Result<u64, CreditError> {
            Ok(10)
        }
        fn calculate_waddleai_tokens(
            &self,
            i: u64,
            o: u64,
            _p: &str,
            _m: &str,
        ) -> Result<u64, CreditError> {
            Ok(i + o)
        }
    }

    pub struct CountingQuota(pub Arc<AtomicUsize>);

    #[async_trait::async_trait]
    impl QuotaBackend for CountingQuota {
        async fn reserve(
            &self,
            _u: &UserContext,
            _m: Option<&str>,
            _msgs: &[Value],
        ) -> Result<Outcome, QuotaError> {
            self.0.fetch_add(1, Ordering::SeqCst);
            Ok(Outcome::proceed())
        }
        async fn reconcile(
            &self,
            _r: &Reservation,
            _a: i64,
            _p: &str,
            _m: &str,
            _c: bool,
        ) -> ReconcileResult {
            ReconcileResult::default()
        }
        async fn release(&self, _r: &Reservation) {}
        fn credits(&self) -> &dyn CreditModel {
            &NoCredits
        }
        fn fault(&self, _k: &str) {}
    }
}

#[tokio::test]
async fn cache_hit_skips_quota_dispatch() {
    use quota::{QuotaStage, POOLED_QUOTA_FLAG};
    let r = rig();
    let reserves = Arc::new(AtomicUsize::new(0));
    let dispatches = Arc::new(Counting::default());
    let on = Arc::new(StaticFlagResolver::new([
        RESPONSE_CACHE_FLAG,
        POOLED_QUOTA_FLAG,
    ]));
    let pipe = ProxyPipeline::new(
        vec![
            Arc::new(CacheStage::new(r.cache.clone())),
            Arc::new(QuotaStage::new(
                Some(Arc::new(quota_fake::CountingQuota(reserves.clone()))),
                on.clone(),
            )),
            Arc::new(FakeDispatch(dispatches.clone())),
        ],
        on,
    );
    // positive control: a miss reserves quota and dispatches
    let mut miss = ctx(7, "gpt-4o", ResponseFormat::Openai, "What is Rust?");
    pipe.run(&mut miss).await.unwrap();
    assert_eq!(reserves.load(Ordering::SeqCst), 1);
    assert_eq!(dispatches.0.load(Ordering::SeqCst), 1);
    assert!(commit_write_back(&miss, &openai_body("Rust is a language."), &json!({})).await);

    // the hit short-circuits both
    let mut hit = ctx(7, "gpt-4o", ResponseFormat::Openai, "What is Rust?");
    pipe.run(&mut hit).await.unwrap();
    assert!(hit.cache_hit && hit.provider.as_deref() == Some("cache"));
    assert_eq!(reserves.load(Ordering::SeqCst), 1, "quota skipped on hit");
    assert_eq!(
        dispatches.0.load(Ordering::SeqCst),
        1,
        "dispatch skipped on hit"
    );
    assert!(hit.quota_release.is_none() && hit.quota_reservation.is_none());
}

