/// Blocks the request, like a security_out verdict of block.
struct BlockingSecurityOut;

#[async_trait::async_trait]
impl Stage for BlockingSecurityOut {
    fn name(&self) -> &'static str {
        "security_out"
    }
    async fn call(&self, ctx: &mut PipelineContext) -> Result<(), StageError> {
        ctx.blocked = true;
        ctx.status_code = 400;
        Ok(())
    }
}

struct PassingSecurityOut;

#[async_trait::async_trait]
impl Stage for PassingSecurityOut {
    fn name(&self) -> &'static str {
        "security_out"
    }
    async fn call(&self, _ctx: &mut PipelineContext) -> Result<(), StageError> {
        Ok(())
    }
}

#[tokio::test]
async fn write_back_only_after_security_out_pass() {
    let on = Arc::new(StaticFlagResolver::new([RESPONSE_CACHE_FLAG]));
    for (blocking, want_puts) in [(true, 0usize), (false, 1usize)] {
        let r = rig();
        let sec: Arc<dyn Stage> = if blocking {
            Arc::new(BlockingSecurityOut)
        } else {
            Arc::new(PassingSecurityOut)
        };
        let pipe = ProxyPipeline::new(
            vec![Arc::new(CacheStage::new(r.cache.clone())), sec],
            on.clone(),
        );
        let mut c = ctx(7, "gpt-4o", ResponseFormat::Openai, "What is Rust?");
        pipe.run(&mut c).await.unwrap();
        assert_eq!(
            r.exact.puts.load(Ordering::SeqCst),
            0,
            "nothing is written during the pipeline"
        );
        let committed =
            commit_write_back(&c, &openai_body("Rust is a language."), &json!({})).await;
        assert_eq!(committed, !blocking);
        assert_eq!(r.exact.puts.load(Ordering::SeqCst), want_puts);
    }
}

